/* ---------------- Convert source tuples to domain rows ---------------- */

function toCustomerMaterialsRow(
  sheetName: CustomerMaterialsSheetName,
  source: SourceRow,
): CustomerMaterialsRow {
  const [
    sourceRow,
    salesCustomer,
    materialType,
    code,
    no,
    description,
    unit,
    openingQuantity,
    receivedIn,
    issuedProduction,
    issuedDamaged,
    issuedOther,
    remainingQuantity,
    physicalCount,
    countDifference,
    remark,
    daily,
  ] = source;

  return {
    sheet_name: sheetName,
    item: {
      source_row: sourceRow,
      sales_customer: salesCustomer,
      material_type: materialType,
      code,
      no,
      description,
      unit,
    },
    summary: {
      opening_quantity: openingQuantity,
      received_in: receivedIn,
      issued_production: issuedProduction,
      issued_damaged: issuedDamaged,
      issued_other: issuedOther,
      remaining_quantity: remainingQuantity,
      physical_count: physicalCount,
      count_difference: countDifference,
    },
    remark,
    daily: daily.map(([day, received, production, damaged, other]) => ({
      day,
      values: {
        received_in: received,
        issued_production: production,
        issued_damaged: damaged,
        issued_other: other,
      },
    })),
  };
}

export const stockCustomerMaterialsMockWorkbook: CustomerMaterialsWorkbook = {
  sheets: sourceSheets.map((sheet) => ({
    name: sheet.name,
    report_caption: sheet.reportCaption,
    period_caption: sheet.periodCaption,
    rows: sheet.rows.map((row) => toCustomerMaterialsRow(sheet.name, row)),
  })),
};
